with open('template.html', 'r', encoding='utf-8') as f:
    template = f.read()
template = template.replace('__FEATURES__', json.dumps(features, ensure_ascii=False))
template = template.replace('__GROUPS__', json.dumps(groups, ensure_ascii=False))
